struct Tile {
  const Terrain* terrain;   // shared, immutable flyweight
  const Terrain* original;  // extrinsic: what to restore
  int thawTurn;             // extrinsic: per-tile timer
};

void castFreeze(World& w, int cx, int cy, int turn) {
  for (int x = cx - 1; x <= cx + 1; x++)
    for (int y = cy - 1; y <= cy + 1; y++) {
      Tile& t = w.tile(x, y);
      if (!t.terrain->isWater()) continue;
      t.original = t.terrain;
      t.terrain  = &w.iceTerrain();  // swap pointer, don't mutate
      t.thawTurn = turn + 10;
    }
}

class World {
public:
  const Terrain& getTile(int x, int y) const {
    return terrains_[tiles_[x][y]];  // same OO API
  }
private:
  Terrain terrains_[TERRAIN_COUNT];      // few, contiguous, cache-hot
  uint8_t tiles_[WIDTH][HEIGHT];         // compact grid
};
